480  int kvm_riscv_vcpu_pmu_event_info(struct kvm_vcpu *vcpu, unsigned long saddr_low, 				  unsigned long saddr_high, unsigned long num_events, 				  unsigned long flags, struct kvm_vcpu_sbi_return *retdata)  {
481  	struct riscv_pmu_event_info *einfo = NULL;
482  	int shmem_size = num_events * sizeof(*einfo);
483  	gpa_t shmem;
484  	u32 eidx, etype;
485  	u64 econfig;
486  	int ret;
487  
488  	if (flags != 0 || (saddr_low & (SZ_16 - 1) || num_events == 0)) {
489  		ret = SBI_ERR_INVALID_PARAM;
490  		goto out;
491  	}
492  
493  	shmem = saddr_low;
494  	if (saddr_high != 0) {
495  		if (IS_ENABLED(CONFIG_32BIT)) {
496  			shmem |= ((gpa_t)saddr_high << 32);
497  		} else {
498  			ret = SBI_ERR_INVALID_ADDRESS;
499  			goto out;
500  		}
501  	}
502  
503  	einfo = kzalloc(shmem_size, GFP_KERNEL);
504  	if (!einfo)
505  		return -ENOMEM;
506  
507  	ret = kvm_vcpu_read_guest(vcpu, shmem, einfo, shmem_size);
508  	if (ret) {
509  		ret = SBI_ERR_FAILURE;
510  		goto free_mem;
511  	}
512  
513  	for (int i = 0; i < num_events; i++) {
514  		eidx = einfo[i].event_idx;
515  		etype = kvm_pmu_get_perf_event_type(eidx);
516  		econfig = kvm_pmu_get_perf_event_config(eidx, einfo[i].event_data);
517  		ret = riscv_pmu_get_event_info(etype, econfig, NULL);
518  		einfo[i].output = (ret > 0) ? 1 : 0;
519  	}
520  
521  	ret = kvm_vcpu_write_guest(vcpu, shmem, einfo, shmem_size);
522  	if (ret)
523  		ret = SBI_ERR_INVALID_ADDRESS;
524  
525  free_mem:
526  	kfree(einfo);
527  out:
528  	retdata->err_val = ret;
529  
530  	return 0;
531  }

