126  		if (ecode < SBI_PMU_HW_GENERAL_MAX)
127  			config = kvm_pmu_get_perf_event_hw_config(ecode);
128  		break;
129  	case SBI_PMU_EVENT_TYPE_CACHE:
130  		config = kvm_pmu_get_perf_event_cache_config(ecode);
