39  void mips_errata_patch_func(struct alt_entry *begin, struct alt_entry *end, 			    unsigned long archid, unsigned long impid, 			    unsigned int stage)  {
40  	struct alt_entry *alt;
41  	u32 cpu_req_errata = mips_errata_probe();
42  	u32 tmp;
43  
44  	BUILD_BUG_ON(ERRATA_MIPS_NUMBER >= RISCV_VENDOR_EXT_ALTERNATIVES_BASE);
45  
46  	if (stage == RISCV_ALTERNATIVES_EARLY_BOOT)
47  		return;
48  
49  	for (alt = begin; alt < end; alt++) {
50  		if (alt->vendor_id != MIPS_VENDOR_ID)
51  			continue;
52  
53  		if (alt->patch_id >= ERRATA_MIPS_NUMBER) {
54  			WARN(1, "MIPS errata id:%d not in kernel errata list\n",
55  			     alt->patch_id);
56  			continue;
57  		}
58  
59  		tmp = (1U << alt->patch_id);
60  		if (cpu_req_errata && tmp) {
61  			mutex_lock(&text_mutex);
62  			patch_text_nosync(ALT_OLD_PTR(alt), ALT_ALT_PTR(alt),
63  					  alt->alt_len);
64  			mutex_unlock(&text_mutex);
65  		}
66  	}
67  }

