290  void kvm_riscv_gstage_wp_range(struct kvm_gstage *gstage, gpa_t start, gpa_t end)  {
291  	int ret;
292  	pte_t *ptep;
293  	u32 ptep_level;
294  	bool found_leaf;
295  	gpa_t addr = start;
296  	unsigned long page_size;
297  
298  	while (addr < end) {
299  		found_leaf = kvm_riscv_gstage_get_leaf(gstage, addr, &ptep, &ptep_level);
300  		ret = gstage_level_to_page_size(ptep_level, &page_size);
301  		if (ret)
302  			break;
303  
304  		if (!found_leaf)
305  			goto next;
306  
307  		addr = ALIGN_DOWN(addr, page_size);
308  		kvm_riscv_gstage_op_pte(gstage, addr, ptep,
309  					ptep_level, GSTAGE_OP_WP);
310  next:
311  		addr += page_size;
312  	}
313  }

