439  static int aia_has_attr(struct kvm_device *dev, struct kvm_device_attr *attr)  {
440  	int nr_vcpus, r = -ENXIO;
441  
442  	switch (attr->group) {
443  	case KVM_DEV_RISCV_AIA_GRP_CONFIG:
444  		switch (attr->attr) {
445  		case KVM_DEV_RISCV_AIA_CONFIG_MODE:
446  		case KVM_DEV_RISCV_AIA_CONFIG_IDS:
447  		case KVM_DEV_RISCV_AIA_CONFIG_SRCS:
448  		case KVM_DEV_RISCV_AIA_CONFIG_GROUP_BITS:
449  		case KVM_DEV_RISCV_AIA_CONFIG_GROUP_SHIFT:
450  		case KVM_DEV_RISCV_AIA_CONFIG_HART_BITS:
451  		case KVM_DEV_RISCV_AIA_CONFIG_GUEST_BITS:
452  			return 0;
453  		}
454  		break;
455  	case KVM_DEV_RISCV_AIA_GRP_ADDR:
456  		nr_vcpus = atomic_read(&dev->kvm->online_vcpus);
457  		if (attr->attr == KVM_DEV_RISCV_AIA_ADDR_APLIC)
458  			return 0;
459  		else if (attr->attr < KVM_DEV_RISCV_AIA_ADDR_IMSIC(nr_vcpus))
460  			return 0;
461  		break;
462  	case KVM_DEV_RISCV_AIA_GRP_CTRL:
463  		switch (attr->attr) {
464  		case KVM_DEV_RISCV_AIA_CTRL_INIT:
465  			return 0;
466  		}
467  		break;
468  	case KVM_DEV_RISCV_AIA_GRP_APLIC:
469  		mutex_lock(&dev->kvm->lock);
470  		r = kvm_riscv_aia_aplic_has_attr(dev->kvm, attr->attr);
471  		mutex_unlock(&dev->kvm->lock);
472  		break;
473  	case KVM_DEV_RISCV_AIA_GRP_IMSIC:
474  		return kvm_riscv_aia_imsic_has_attr(dev->kvm, attr->attr);
475  	}
476  
477  	return r;
478  }

