29  static void hwprobe_arch_id(struct riscv_hwprobe *pair, 			    const struct cpumask *cpus)  {
30  	u64 id = -1ULL;
31  	bool first = true;
32  	int cpu;
33  
34  	for_each_cpu(cpu, cpus) {
35  		u64 cpu_id;
36  
37  		switch (pair->key) {
38  		case RISCV_HWPROBE_KEY_MVENDORID:
39  			cpu_id = riscv_cached_mvendorid(cpu);
40  			break;
41  		case RISCV_HWPROBE_KEY_MIMPID:
42  			cpu_id = riscv_cached_mimpid(cpu);
43  			break;
44  		case RISCV_HWPROBE_KEY_MARCHID:
45  			cpu_id = riscv_cached_marchid(cpu);
46  			break;
47  		}
48  
49  		if (first) {
50  			id = cpu_id;
51  			first = false;
52  		}
53  
54  		/*
55  		 * If there's a mismatch for the given set, return -1 in the
56  		 * value.
57  		 */
58  		if (id != cpu_id) {
59  			id = -1ULL;
60  			break;
61  		}
62  	}
63  
64  	pair->value = id;
65  }

