511  int handle_misaligned_store(struct pt_regs *regs)  {
512  	union reg_data val;
513  	unsigned long epc = regs->epc;
514  	unsigned long insn;
515  	unsigned long addr = regs->badaddr;
516  	int i, len = 0, fp = 0;
517  
518  	perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS, 1, regs, addr);
519  
520  	if (!unaligned_enabled)
521  		return -1;
522  
523  	if (user_mode(regs) && (current->thread.align_ctl & PR_UNALIGN_SIGBUS))
524  		return -1;
525  
526  	if (get_insn(regs, epc, &insn))
527  		return -1;
528  
529  	regs->epc = 0;
530  
531  	val.data_ulong = GET_RS2(insn, regs);
532  
533  	if ((insn & INSN_MASK_SW) == INSN_MATCH_SW) {
534  		len = 4;
535  #if defined(CONFIG_64BIT)
536  	} else if ((insn & INSN_MASK_SD) == INSN_MATCH_SD) {
537  		len = 8;
538  #endif
539  	} else if ((insn & INSN_MASK_FSD) == INSN_MATCH_FSD) {
540  		fp = 1;
541  		len = 8;
542  		val.data_u64 = GET_F64_RS2(insn, regs);
543  	} else if ((insn & INSN_MASK_FSW) == INSN_MATCH_FSW) {
544  		fp = 1;
545  		len = 4;
546  		val.data_ulong = GET_F32_RS2(insn, regs);
547  	} else if ((insn & INSN_MASK_SH) == INSN_MATCH_SH) {
548  		len = 2;
549  #if defined(CONFIG_64BIT)
550  	} else if ((insn & INSN_MASK_C_SD) == INSN_MATCH_C_SD) {
551  		len = 8;
552  		val.data_ulong = GET_RS2S(insn, regs);
553  	} else if ((insn & INSN_MASK_C_SDSP) == INSN_MATCH_C_SDSP &&
554  		   ((insn >> SH_RD) & 0x1f)) {
555  		len = 8;
556  		val.data_ulong = GET_RS2C(insn, regs);
557  #endif
558  	} else if ((insn & INSN_MASK_C_SW) == INSN_MATCH_C_SW) {
559  		len = 4;
560  		val.data_ulong = GET_RS2S(insn, regs);
561  	} else if ((insn & INSN_MASK_C_SWSP) == INSN_MATCH_C_SWSP &&
562  		   ((insn >> SH_RD) & 0x1f)) {
563  		len = 4;
564  		val.data_ulong = GET_RS2C(insn, regs);
565  	} else if ((insn & INSN_MASK_C_FSD) == INSN_MATCH_C_FSD) {
566  		fp = 1;
567  		len = 8;
568  		val.data_u64 = GET_F64_RS2S(insn, regs);
569  	} else if ((insn & INSN_MASK_C_FSDSP) == INSN_MATCH_C_FSDSP) {
570  		fp = 1;
571  		len = 8;
572  		val.data_u64 = GET_F64_RS2C(insn, regs);
573  #if !defined(CONFIG_64BIT)
574  	} else if ((insn & INSN_MASK_C_FSW) == INSN_MATCH_C_FSW) {
575  		fp = 1;
576  		len = 4;
577  		val.data_ulong = GET_F32_RS2S(insn, regs);
578  	} else if ((insn & INSN_MASK_C_FSWSP) == INSN_MATCH_C_FSWSP) {
579  		fp = 1;
580  		len = 4;
581  		val.data_ulong = GET_F32_RS2C(insn, regs);
582  #endif
583  	} else {
584  		regs->epc = epc;
585  		return -1;
586  	}
587  
588  	if (!IS_ENABLED(CONFIG_FPU) && fp)
589  		return -EOPNOTSUPP;
590  
591  	for (i = 0; i < len; i++) {
592  		if (store_u8(regs, (void *)(addr + i), val.data_bytes[i]))
593  			return -1;
594  	}
595  
596  	regs->epc = epc + INSN_LEN(insn);
597  
598  	return 0;
599  }

