785  int kvm_riscv_vcpu_aia_imsic_update(struct kvm_vcpu *vcpu)  {
786  	unsigned long flags;
787  	phys_addr_t new_vsfile_pa;
788  	struct imsic_mrif tmrif;
789  	void __iomem *new_vsfile_va;
790  	struct kvm *kvm = vcpu->kvm;
791  	struct kvm_run *run = vcpu->run;
792  	struct kvm_vcpu_aia *vaia = &vcpu->arch.aia_context;
793  	struct imsic *imsic = vaia->imsic_state;
794  	int ret = 0, new_vsfile_hgei = -1, old_vsfile_hgei, old_vsfile_cpu;
795  
796  	/* Do nothing for emulation mode */
797  	if (kvm->arch.aia.mode == KVM_DEV_RISCV_AIA_MODE_EMUL)
798  		return 1;
799  
800  	/* Read old IMSIC VS-file details */
801  	read_lock_irqsave(&imsic->vsfile_lock, flags);
802  	old_vsfile_hgei = imsic->vsfile_hgei;
803  	old_vsfile_cpu = imsic->vsfile_cpu;
804  	read_unlock_irqrestore(&imsic->vsfile_lock, flags);
805  
806  	/* Do nothing if we are continuing on same CPU */
807  	if (old_vsfile_cpu == vcpu->cpu)
808  		return 1;
809  
810  	/* Allocate new IMSIC VS-file */
811  	ret = kvm_riscv_aia_alloc_hgei(vcpu->cpu, vcpu,
812  				       &new_vsfile_va, &new_vsfile_pa);
813  	if (ret <= 0) {
814  		/* For HW acceleration mode, we can't continue */
815  		if (kvm->arch.aia.mode == KVM_DEV_RISCV_AIA_MODE_HWACCEL) {
816  			run->fail_entry.hardware_entry_failure_reason =
817  								KVM_EXIT_FAIL_ENTRY_NO_VSFILE;
818  			run->fail_entry.cpu = vcpu->cpu;
819  			run->exit_reason = KVM_EXIT_FAIL_ENTRY;
820  			return 0;
821  		}
822  
823  		/* Release old IMSIC VS-file */
824  		if (old_vsfile_cpu >= 0)
825  			kvm_riscv_vcpu_aia_imsic_release(vcpu);
826  
827  		/* For automatic mode, we continue */
828  		goto done;
829  	}
830  	new_vsfile_hgei = ret;
831  
832  	/*
833  	 * At this point, all interrupt producers are still using
834  	 * to the old IMSIC VS-file so we first move all interrupt
835  	 * producers to the new IMSIC VS-file.
836  	 */
837  
838  	/* Ensure HGEIE CSR bit is zero before using the new IMSIC VS-file */
839  	csr_clear(CSR_HGEIE, BIT(new_vsfile_hgei));
840  
841  	/* Zero-out new IMSIC VS-file */
842  	imsic_vsfile_local_clear(new_vsfile_hgei, imsic->nr_hw_eix);
843  
844  	/* Update G-stage mapping for the new IMSIC VS-file */
845  	ret = kvm_riscv_mmu_ioremap(kvm, vcpu->arch.aia_context.imsic_addr,
846  				    new_vsfile_pa, IMSIC_MMIO_PAGE_SZ,
847  				    true, true);
848  	if (ret)
849  		goto fail_free_vsfile_hgei;
850  
851  	/* TODO: Update the IOMMU mapping ??? */
852  
853  	/* Update new IMSIC VS-file details in IMSIC context */
854  	write_lock_irqsave(&imsic->vsfile_lock, flags);
855  	imsic->vsfile_hgei = new_vsfile_hgei;
856  	imsic->vsfile_cpu = vcpu->cpu;
857  	imsic->vsfile_va = new_vsfile_va;
858  	imsic->vsfile_pa = new_vsfile_pa;
859  	write_unlock_irqrestore(&imsic->vsfile_lock, flags);
860  
861  	/*
862  	 * At this point, all interrupt producers have been moved
863  	 * to the new IMSIC VS-file so we move register state from
864  	 * the old IMSIC VS/SW-file to the new IMSIC VS-file.
865  	 */
866  
867  	memset(&tmrif, 0, sizeof(tmrif));
868  	if (old_vsfile_cpu >= 0) {
869  		/* Read and clear register state from old IMSIC VS-file */
870  		imsic_vsfile_read(old_vsfile_hgei, old_vsfile_cpu,
871  				  imsic->nr_hw_eix, true, &tmrif);
872  
873  		/* Free-up old IMSIC VS-file */
874  		kvm_riscv_aia_free_hgei(old_vsfile_cpu, old_vsfile_hgei);
875  	} else {
876  		/* Read and clear register state from IMSIC SW-file */
877  		imsic_swfile_read(vcpu, true, &tmrif);
878  	}
879  
880  	/* Restore register state in the new IMSIC VS-file */
881  	imsic_vsfile_local_update(new_vsfile_hgei, imsic->nr_hw_eix, &tmrif);
882  
883  done:
884  	/* Set VCPU HSTATUS.VGEIN to new IMSIC VS-file */
885  	vcpu->arch.guest_context.hstatus &= ~HSTATUS_VGEIN;
886  	if (new_vsfile_hgei > 0)
887  		vcpu->arch.guest_context.hstatus |=
888  			((unsigned long)new_vsfile_hgei) << HSTATUS_VGEIN_SHIFT;
889  
890  	/* Continue run-loop */
891  	return 1;
892  
893  fail_free_vsfile_hgei:
894  	kvm_riscv_aia_free_hgei(vcpu->cpu, new_vsfile_hgei);
895  	return ret;
896  }

