81  static void die_kernel_fault(const char *msg, unsigned long addr, 		struct pt_regs *regs)  {
82  	bust_spinlocks(1);
83  
84  	pr_alert("Unable to handle kernel %s at virtual address " REG_FMT "\n", msg,
85  		addr);
86  
87  	bust_spinlocks(0);
88  	show_pte(addr);
89  	die(regs, "Oops");
90  	make_task_dead(SIGKILL);
91  }

