245  static u32 imsic_mrif_topei(struct imsic_mrif *mrif, u32 nr_eix, u32 nr_msis)  {
246  	struct imsic_mrif_eix *eix;
247  	u32 i, imin, imax, ei, max_msi;
248  	unsigned long eipend[BITS_PER_TYPE(u64) / BITS_PER_LONG];
249  	unsigned long eithreshold = imsic_mrif_atomic_read(mrif,
250  							&mrif->eithreshold);
251  
252  	max_msi = (eithreshold && (eithreshold <= nr_msis)) ?
253  		   eithreshold : nr_msis;
254  	for (ei = 0; ei < nr_eix; ei++) {
255  		eix = &mrif->eix[ei];
256  		eipend[0] = imsic_mrif_atomic_read(mrif, &eix->eie[0]) &
257  			    imsic_mrif_atomic_read(mrif, &eix->eip[0]);
258  #ifdef CONFIG_32BIT
259  		eipend[1] = imsic_mrif_atomic_read(mrif, &eix->eie[1]) &
260  			    imsic_mrif_atomic_read(mrif, &eix->eip[1]);
261  		if (!eipend[0] && !eipend[1])
262  #else
263  		if (!eipend[0])
264  #endif
265  			continue;
266  
267  		imin = ei * BITS_PER_TYPE(u64);
268  		imax = ((imin + BITS_PER_TYPE(u64)) < max_msi) ?
269  			imin + BITS_PER_TYPE(u64) : max_msi;
270  		for (i = (!imin) ? 1 : imin; i < imax; i++) {
271  			if (test_bit(i - imin, eipend))
272  				return (i << TOPEI_ID_SHIFT) | i;
273  		}
274  	}
275  
276  	return 0;
277  }

