328  		} else {
329  			pend = false;
330  			num = isel - IMSIC_EIE0;
331  		}
332  
333  		if ((num / 2) >= nr_eix)
334  			return -EINVAL;
335  		eix = &mrif->eix[num / 2];
336  
337  #ifndef CONFIG_32BIT
338  		if (num & 0x1)
339  			return -EINVAL;
340  		ei = (pend) ? &eix->eip[0] : &eix->eie[0];
341  #else
342  		ei = (pend) ? &eix->eip[num & 0x1] : &eix->eie[num & 0x1];
343  #endif
344  
345  		/* Bit0 of EIP0 or EIE0 is read-only */
346  		if (!num)
347  			wr_mask &= ~BIT(0);
348  
349  		old_val = imsic_mrif_atomic_rmw(mrif, ei, new_val, wr_mask);
350  		break;
351  	default:
352  		return -ENOENT;
353  	}
354  
355  	if (val)
356  		*val = old_val;
357  
358  	return 0;
359  }

