489  static int imsic_vsfile_rw(int vsfile_hgei, int vsfile_cpu, u32 nr_eix, 			   unsigned long isel, bool write, 			   unsigned long *val)  {
490  	int rc;
491  	struct imsic_vsfile_rw_data rdata;
492  
493  	/* We can only access register if we have a IMSIC VS-file */
494  	if (vsfile_cpu < 0 || vsfile_hgei <= 0)
495  		return -EINVAL;
496  
497  	/* Check IMSIC register iselect */
498  	rc = imsic_mrif_isel_check(nr_eix, isel);
499  	if (rc)
500  		return rc;
501  
502  	/* We can only access register on local CPU */
503  	rdata.hgei = vsfile_hgei;
504  	rdata.isel = isel;
505  	rdata.write = write;
506  	rdata.val = (write) ? *val : 0;
507  	on_each_cpu_mask(cpumask_of(vsfile_cpu),
508  			 imsic_vsfile_local_rw, &rdata, 1);
509  
510  	if (!write)
511  		*val = rdata.val;
512  
513  	return 0;
514  }

