280  static int imsic_mrif_isel_check(u32 nr_eix, unsigned long isel)  {
281  	u32 num = 0;
282  
283  	switch (isel) {
284  	case IMSIC_EIDELIVERY:
285  	case IMSIC_EITHRESHOLD:
286  		break;
287  	case IMSIC_EIP0 ... IMSIC_EIP63:
288  		num = isel - IMSIC_EIP0;
289  		break;
290  	case IMSIC_EIE0 ... IMSIC_EIE63:
291  		num = isel - IMSIC_EIE0;
292  		break;
293  	default:
294  		return -ENOENT;
295  	}
296  #ifndef CONFIG_32BIT
297  	if (num & 0x1)
298  		return -EINVAL;
299  #endif
300  	if ((num / 2) >= nr_eix)
301  		return -EINVAL;
302  
303  	return 0;
304  }

